// Obtener items RSS
const items = $input.all();

// Ordenar por fecha
items.sort((a, b) => {
  return new Date(b.json.pubDate) - new Date(a.json.pubDate);
});

// Tomar solo 10
const top10 = items.slice(0, 10);

// Función resumen simple
function resumir(texto) {

  if (!texto) return "Sin resumen.";

  // limpiar HTML
  texto = texto.replace(/<[^>]*>/g, '');

  // cortar frases
  const frases = texto.split('.');

  // primeras 2 frases
  return frases.slice(0, 2).join('.') + '.';
}


const ahora = new Date();

// Función para agregar ceros
function pad(n) {
  return n.toString().padStart(2, '0');
}

// Fecha y hora
const año = ahora.getFullYear();
const mes = pad(ahora.getMonth() + 1);
const dia = pad(ahora.getDate());

const hora = pad(ahora.getHours());
const minutos = pad(ahora.getMinutes());
const segundos = pad(ahora.getSeconds());

// Timestamp final
const timestamp = `${año}${mes}${dia}_${hora}${minutos}${segundos}`;

// Nombres de archivo
//const nombreHTML = `Noticias_${timestamp}.html`;
const nombreHTML = 'Notiias.html'
const nombrePDF = `Noticias_${timestamp}.pdf`;

// Obtener HTML generado
const html = $input.first().json.html;



// Crear nuevo array
const noticias = top10.map((item, index) => {

  return {
    json: {
      numero: index + 1,
      titulo: item.json.title,
      link: item.json.link,
      fecha: item.json.pubDate,
      resumen: resumir(
        item.json.contentSnippet ||
        item.json.content ||
        item.json.title
      ),
      html,
      nombreHTML,
      nombrePDF,
      timestamp
    }
  };
});

return noticias;
